edges = []
for i in range(13):
    for j in [1, 2, 3]:
        u = i
        v = (i + j) % 13
        if u < v:
            edges.append((u, v))
        else:
            edges.append((v, u))
edges = list(set(edges))
edges.sort()
flattened = []
for u, v in edges:
    flattened.extend([u, v])
print(flattened)
